import { describe, expect, it } from "vitest";
import { UserSchema } from "../src/models/user.schema";

const now = new Date();
const valid = { id: "1", email: "ada@example.com", name: "Ada", createdAt: now, updatedAt: now };

describe("UserSchema", () => {
  it("accepts a well-formed user", () => {
    expect(UserSchema.safeParse(valid).success).toBe(true);
  });

  it("rejects users with a malformed email", () => {
    expect(UserSchema.safeParse({ ...valid, email: "not-an-email" }).success).toBe(false);
  });
});

